widget.client_script:
function ($scope, $rootScope, spModal, $window) {
  var c = this;
  c.filtersCollapsed = false;
  c.toggleFilters = function () {
    c.filtersCollapsed = !c.filtersCollapsed;
  };
  $scope.data.estimateMax = $scope.data.estimateMax || 10000000;
  $scope.data.estimateLow = 0;
  $scope.data.estimateHigh = $scope.data.estimateMax;
  $scope.updateTrack = function () {
    if ($scope.data.estimateLow > $scope.data.estimateHigh) {
      $scope.data.estimateLow = $scope.data.estimateHigh;
    }
  };
  $scope.onAdvancedChange = function () {
    var currentURL = new URL($window.location.href);
    if ($scope.data.isPostponed || $scope.data.isEmergency || $scope.data.license ||
        $scope.data.advertDate || $scope.data.bidDate || $scope.data.keyword || $scope.data.estimate) {
      currentURL.searchParams.delete('keyword');
      currentURL.searchParams.delete('license');
      currentURL.searchParams.delete('advertDate');
      currentURL.searchParams.delete('bidDate');
      currentURL.searchParams.delete('estimate');
      currentURL.searchParams.delete('postponed');
      currentURL.searchParams.delete('emergency');
    }
    $window.history.replaceState({}, '', currentURL);
    $window.sessionStorage.setItem(
      'myWidget.advancedFilters',
      $scope.data.advanced.toString()
    );
  };
  $scope.selectedTrackBackground = function () {
    var low = parseFloat($scope.data.estimateLow);
    var high = parseFloat($scope.data.estimateHigh);
    var max = parseFloat($scope.data.estimateMax);
var lowPercent = (low / max) * 100;
var highPercent = (high / max) * 100;
    return 'linear-gradient(to right, #d7dcdf 0%, #d7dcdf ' + lowPercent + '%, #0072c6 ' +
      lowPercent + '%, #0072c6 ' + highPercent + '%, #d7dcdf ' + highPercent +
      '%, #d7dcdf 100%)';
  };
  $scope.changeFilters = function (filter) {
    var currentURL = new URL($window.location.href);
    var selectedFilter = $scope.data.filter;
    if (filter == 'timespan') {
      currentURL.searchParams.set('timespan', selectedFilter);
    } else if (filter == 'postponed') {
      if ($scope.data.isPostponed === true) currentURL.searchParams.set('postponed', $scope.data.isPostponed);
      else currentURL.searchParams.delete('postponed');
    } else if (filter == 'emergency') {
      if ($scope.data.isEmergency === true) currentURL.searchParams.set('emergency', $scope.data.isEmergency);
      else currentURL.searchParams.delete('emergency');
    }
    $window.history.replaceState({}, '', currentURL);
  };
  $scope.initializeDatesAndDropdowns = function () {
    var currentURL = new URL($window.location.href);
    $scope.data.isPostponed = currentURL.searchParams.get('postponed') === 'true';
    $scope.data.isEmergency = currentURL.searchParams.get('emergency') === 'true';
    var saved = $window.sessionStorage.getItem('myWidget.advancedFilters');
    $scope.data.advanced = (saved === 'true');
    if ($scope.data.isPostponed || $scope.data.isEmergency || $scope.data.license ||
        $scope.data.advertDate || $scope.data.bidDate || $scope.data.keyword || $scope.data.estimate) {
      $scope.data.advanced = true;
    }
    var projectParam = $scope.data.project;
    var district = $scope.data.district;
    if (district) {
      var dropdown = document.getElementById('district');
      for (var i = 0; i < dropdown.options.length; i++) {
        if (dropdown.options[i].value === district) {
          dropdown.selectedIndex = i;
          break;
        }
      }
      if (projectParam) {
        dropdown = document.getElementById('project');
        for (var j = 0; j < dropdown.options.length; j++) {
          if (dropdown.options[j].value === projectParam) {
            dropdown.selectedIndex = j;
            break;
          }
        }
      }
    }
    if ($scope.data.advertDate) document.getElementById('advertDate').value = $scope.data.advertDate;
    if ($scope.data.bidDate) document.getElementById('bidDate').value = $scope.data.bidDate;
  };
  $scope.changeParam = function (name) {
    var currentURL = new URL($window.location.href);
    var el = document.getElementById(name);
    var value = el ? el.value.trim() : '';
    if (value.length > 0) currentURL.searchParams.set(name, value);
    else currentURL.searchParams.delete(name);
    if (name == 'advertDate') currentURL.searchParams.delete('timespan');
    $window.history.replaceState({}, '', currentURL);
  };
  $scope.searchFunction = function () {
    var currentURL = new URL($window.location.href);
    var params = ['contract', 'project', 'keyword', 'district', 'license', 'advertDate', 'bidDate', 'bidItems', 'estimate'];
    for (var i = 0; i < params.length; i++) {
      var el = document.getElementById(params[i]);
      if (!el) {
        currentURL.searchParams.delete(params[i]);
        continue;
      }
      var value = el.value.trim();
      if (value.length > 0) currentURL.searchParams.set(params[i], value);
      else currentURL.searchParams.delete(params[i]);
      if (params[i] == 'advertDate' && value.length > 0) currentURL.searchParams.delete('timespan');
    }
    $window.history.replaceState({}, '', currentURL);
  };
  $scope.server.update().then(function () {
    $scope.initializeDatesAndDropdowns();
  });
  $scope.sortBy = function (sortField) {
    $rootScope.$broadcast('triggerSortFunction', { param: sortField });
  };
  c.openOverlay = function () {
    var articleId = c.data.finalSysId;
    spModal.open({
      widget: 'cc_modal_kb_article',
      widgetInput: { sys_id: articleId },
      size: 'lg'
    });
  };
}

