widget.client_script:
function ($scope, $location, $rootScope, spUtil, $interpolate, spAriaFocusManager, $timeout) {
    var c = this;

		c.data.filters = [];
		if (c.data.contractNumberSearch){
			c.data.filters.push('Contract number containing ' + c.data.contractNumberSearch);
			c.data.searching = true;
		}
		if (c.data.project){
			c.data.filters.push('Contract number ' + c.data.project);
			c.data.searching = true;
		}
		if (c.data.keywordSearch){
			c.data.filters.push('Work description containing ' + c.data.keywordSearch);
			c.data.searching = true;
		}
		if (c.data.districtParam){
			c.data.filters.push('Contracts in district ' + c.data.districtNums);
			c.data.searching = true;
		}
		if (c.data.license){
			c.data.filters.push('License ' + c.data.license);
			c.data.searching = true;
		}
		if (c.data.bidDate){
			c.data.filters.push('Bid Opening Date ' + c.data.bidDate);
			c.data.searching = true;
		}

		if (c.data.estimate){
			c.data.filters.push('Estimate Amount ' + c.data.estimate);
			c.data.searching = true;
		}
		if (c.data.postponed){
			c.data.filters.push('Postponed true');
			c.data.searching = true;
		}	
		if (c.data.emergency){
			c.data.filters.push('Emergency true');
			c.data.searching = true;
		}

		if(c.data.advertDate){
			c.data.searching = true;
		}

		$scope.removeSearch = function(){
			var currentURL = new URL(window.location.href);

			if($scope.data.contractNumberSearch){
				currentURL.searchParams.delete('contract');
			}
			if($scope.data.districtParam){
				currentURL.searchParams.delete('district');
			}
			if($scope.data.keywordSearch){
				currentURL.searchParams.delete('keyword');
			}
			if($scope.data.license){
				currentURL.searchParams.delete('license');
			}
			if($scope.data.project){
				currentURL.searchParams.delete('project');
			}
			if($scope.data.advertDate){
				currentURL.searchParams.delete('advertDate');
			}
			if($scope.data.bidDate){
				currentURL.searchParams.delete('bidDate');
			}
			if($scope.data.bidItems){
				currentURL.searchParams.delete('bidItems');
			}
			if($scope.data.estimate){
				currentURL.searchParams.delete('estimate');
			}
			if($scope.data.postponed){
				currentURL.searchParams.delete('postponed');
			}
			if($scope.data.emergency){
				currentURL.searchParams.delete('emergency');
			}


			window.history.replaceState({}, '', currentURL);
	}
    c.data.filterText = "";
    c.showFilter = false;

		$scope.sortField = 'advertisement_date';
		$scope.sortDescending = true;
		$scope.sortString = '(Descending)';

		$rootScope.$on('triggerSortFunction', function(event, data){
			$scope.sortBy(data.param);
		});

		$scope.sortBy = function(field){
			console.log('Sort by triggered for field:', field);
			if($scope.sortField === field){
				$scope.sortDescending = !$scope.sortDescending;
				if($scope.sortDescending){
					$scope.sortString = '(Descending)';
				}
				else{
					$scope.sortString = '(Ascending)';
				}
			}
			else{
				$scope.sortField = field;
				$scope.sortDescending = true;
				$scope.sortString = '(Descending)';
			}
		};

		$scope.getSortValue = function(item){
			switch($scope.sortField){
				case 'advertisement_date':
					return item.secondary_fields[2].display_value || '';
				case 'bid_open_date':
					return item.secondary_fields[7].display_value || '';
				case 'state_project_number':
					return item.display_field.display_value || '';
				default:
					return '';
			}
		}
    c.onClick = function ($event, item, url, action) {
        $event.stopPropagation();
        $event.preventDefault();
        if (typeof url == "string") {
            var urlExp = $interpolate(url);
            url = urlExp(item);
            $location.url(url);
        } else if (url && typeof url == "object") {
            $location.search(url);
        } else {
            var evt = {};
            evt.url = url;
            evt.table = item.className;
            evt.sys_id = item.sys_id;
            evt.record = item;
            evt.rectangle_id = c.options.sys_id;
            evt.action = action;
            $location.search('sl_sys_id', evt.sys_id);
            $location.search('sl_table', evt.table);
$location.search('spa', 1);
            $rootScope.$broadcast('$sp.list.click', evt);
        }
        $rootScope.$on('sp.page.loaded', function () {
            $timeout(function () {
                spAriaFocusManager.focusOnPageTitle();
            });
        });
    };
    if (c.options.table && c.options.disable_record_watcher != 'true') {
        spUtil.recordWatch($scope, c.options.table, c.options.filter);
    }
    c.getMaxShownLabel = function (maxEntries, totalCount) {
        if (maxEntries == -1) {
            maxEntries = totalCount;
        }
        if (totalCount == c.data.maxCount || c.data.showGM) {
            if (maxEntries == 1) {
                return "Showing [0] record".replace('[0]', maxEntries);
            }
            return "Showing first [0] records".replace('[0]', maxEntries);
        }
        return "First [0] of [1]".replace('[0]', maxEntries).replace('[1]', totalCount);
    };
    c.seeAllPage = c.options.list_page_dv || 'list';
    c.targetPageID = (c.options.sp_page) ? "&target_page_id=" + c.options.sp_page : "";
    c.getMaxHeight = function () {
        return c.options.panel_body_height || 'none';
    };
    c.getActionColor = function (action) {
        return "text-" + action.color;
    };
    c.update = function update() {
        c.server.update();
    };
    c.toggleFilter = function () {
        c.showFilter = !c.showFilter;
    };
}
